function show(h,n){cur=h;curN=n;$('#mb').innerHTML=`<button class="btn" onclick="dl('pdf')">PDF</button><button class="btn" onclick="dl('png')">PNG</button><button class="btn" onclick="dl('jpg')">JPG</button><button class="btn" onclick="dl('svg')">SVG</button><button class="btn s" onclick="$('#mod').style.display='none'">إغلاق</button>`;$('#pvw').innerHTML=h;$('#mod').style.display='block';{const w=$('#pvw');w.style.setProperty('--z',1);w.style.setProperty('--z',Math.min(1,(w.clientWidth-4)/w.firstElementChild.offsetWidth))}}
async function dl(f){const w=document.createElement('div');w.style.cssText='position:fixed;left:-3000px;top:0';w.innerHTML=cur;document.body.appendChild(w);
try{const el=w.firstElementChild;let blob;
if(f=='svg'){const css=[...document.querySelectorAll('style')].map(s=>s.textContent).join('\n'),W=el.offsetWidth,H=el.offsetHeight;
blob=new Blob([`<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}"><foreignObject width="100%" height="100%"><div xmlns="http://www.w3.org/1999/xhtml"><style><![CDATA[${css}]]></style>${new XMLSerializer().serializeToString(el)}</div></foreignObject></svg>`],{type:'image/svg+xml'})}
else{await document.fonts.ready;const cv=await html2canvas(el,{scale:3,backgroundColor:'#fff',useCORS:true});
if(f=='pdf'){const{jsPDF}=window.jspdf;const d=new jsPDF({orientation:cv.width>cv.height?'l':'p',unit:'px',format:[cv.width/3,cv.height/3]});d.addImage(cv.toDataURL('image/jpeg',.95),'JPEG',0,0,cv.width/3,cv.height/3);blob=d.output('blob')}
else blob=await new Promise(r=>cv.toBlob(r,f=='jpg'?'image/jpeg':'image/png',.95))}
await fsave(curN+'.'+f,blob)}catch(e){if(!e||e.code!='declined')toast('تعذر التنزيل: '+((e&&e.message)||e))}finally{w.remove()}}
async function fsave(name,data){let D=null;try{D=window.claude&&claude.use?await claude.use('downloads'):null}catch(e){}
if(D){await D.save({filename:name,data});return}
const b=data instanceof Blob?data:new Blob([data],{type:/\.csv$/.test(name)?'text/csv;charset=utf-8':'application/octet-stream'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},3000);await new Promise(r=>setTimeout(r,250))}
