function decide(id,yes){const r=S.requests.find(x=>x.id==id);
if(yes){const sid='ST-2026-'+pad(S.n.st++),p=pw();S.students.push({id:sid,name:r.name,email:r.email,phone:r.phone,nat:r.nat,pid:r.pid,prog:DIP,reg:[],sp:[],status:'منتظم',pass:p,exlang:r.exlang||'',adm:window.adm48def?adm48def():undefined});r.status='مقبول';r.sid=sid;flash=`تم القبول. الرقم الأكاديمي: <b>${sid}</b> · الدخول برقم الجواز: <b>${esc(r.pid)}</b> · كلمة المرور: <b>${p}</b> · <a href="mailto:${esc(r.email)}?subject=${encodeURIComponent('قبول وتهنئة - بيانات الدخول')}&body=${encodeURIComponent('السلام عليكم '+r.name+'\nمبارك قبولك في معهد التمهيد.\nاسم المستخدم (رقم الجواز): '+r.pid+'\nكلمة المرور: '+p+'\nرابط البوابة: '+location.href.split('#')[0]+'#/login')}">إرسال رسالة القبول والتهنئة بالبريد</a>`}else{r.status='مرفوض';flash='تم رفض الطلب.'}save();go()}
function stat(id,v){const s=S.students.find(s=>s.id==id);if(!s)return;s.status=v;s.u=new Date().toISOString();save()}
function addTF(f){const v=fv(f),id='TF-2026-'+pad(S.n.tf++),p=pw();S.faculty.push({id,name:v.name,role:v.role,spec:v.spec,courses:[+v.c],pass:p,active:true});save();flash=`أُضيف العضو. رقم العضوية: <b>${id}</b> · كلمة المرور: <b>${p}</b>`;go();return false}
function togTF(id){const f=S.faculty.find(x=>x.id==id);f.active=!f.active;save();go()}
const prForm=(p,act,btn)=>`<form onsubmit="return ${act}(this)"><label>الاسم<input name="name" required value="${esc(p.name)}"></label><label>الوصف<input name="desc" required value="${esc(p.desc)}"></label><label>المشرف<input name="teacher" required value="${esc(p.teacher)}"></label><label>من<input name="from" type="date" required value="${esc(p.from)}"></label><label>إلى<input name="to" type="date" required value="${esc(p.to)}"></label><label>الساعات<input name="hours" type="number" required value="${esc(p.hours)}"></label><label>الرسوم<input name="fee" value="${esc(p.fee||'مجاني')}"></label><label>الخطة<input name="plan" required value="${esc(p.plan)}"></label><button class="btn">${btn}</button>${p.id?' <button type="button" class="btn s" onclick="pre=null;go()">إلغاء التعديل</button>':''}</form>`;
let pre=null;
const prTab=()=>{const e=S.programs.find(x=>x.id==pre);return (e?`<div class="box"><h3>تعديل البرنامج</h3>${prForm(e,'savePr','حفظ التعديلات')}</div><hr>`:`<div class="box"><h3>إضافة برنامج أو دورة</h3>${prForm({},'addPr','إضافة')}</div><hr>`)+tbl(['البرنامج','الفترة','الساعات','الرسوم','الحالة','إجراءات'],S.programs.map(p=>`<tr><td>${esc(p.name)}</td><td>${p.from} ← ${p.to}</td><td>${p.hours}</td><td>${esc(p.fee)}</td><td><span class="tag ${p.cancelled?'er':''}">${pst(p)}</span></td><td><button class="btn s" onclick="pre=${p.id};go()">تعديل</button> <button class="btn s" onclick="togPr(${p.id})">${p.cancelled?'إعادة التفعيل':'إلغاء'}</button> <button class="btn d" onclick="delPr(${p.id})">حذف</button></td></tr>`))};
function savePr(f){const v=fv(f),p=S.programs.find(x=>x.id==pre);if(!p)return false;Object.assign(p,v,{hours:+v.hours});pre=null;save();flash='حُفظت تعديلات البرنامج.';go();return false}
function togPr(id){const p=S.programs.find(x=>x.id==id);p.cancelled=!p.cancelled;save();flash=p.cancelled?'أُلغي البرنامج: لن يظهر للتسجيل، وتبقى بيانات من سُجّلوا فيه ووثائقهم.':'أُعيد تفعيل البرنامج.';go()}
function delPr(id){const p=S.programs.find(x=>x.id==id),u=S.students.filter(x=>x.prog==id).length+S.requests.filter(x=>x.prog==id).length+S.certs.filter(x=>x.prog==id).length+S.faculty.filter(x=>(x.courses||[]).includes(id)).length;
if(u){flash=`لا يمكن حذف «${esc(p.name)}» لارتباطه بـ ${u} سجلاً (طلاب/طلبات/وثائق/هيئة). استخدم «إلغاء» لإخفائه مع حفظ السجلات.`;go();return}
if(dq&&dq.k=='pr'&&dq.id==id){S.programs=S.programs.filter(x=>x.id!=id);dq=null;flash='حُذف البرنامج.'}else{dq={k:'pr',id};flash='اضغط «حذف» مرة ثانية على البرنامج نفسه للتأكيد.'}save();go()}
function addPr(f){const v=fv(f);S.programs.push({...v,id:Date.now(),hours:+v.hours});save();flash='أُضيف البرنامج.';go();return false}
function issue(f){const v=fv(f),s=S.students.find(x=>x.id==v.sid),name=v.name||(s&&s.name)||(FR(v.type)?v.title:'');if(!name){toast(FR(v.type)?'أدخل عنوان الوثيقة أو اسم المستفيد':'أدخل الاسم أو اختر طالباً');return false}
const rec=v51Serial(0,v.type);S.certs.push({...v,rec,sid:s?s.id:'',name,nameEn:v.nameEn,prog:FR(v.type)?0:+v.prog,...(FR(v.type)?{nmShown:!!(v.name||(s&&s.name))&&v.showName!='0'}:{}),date:new Date().toISOString().slice(0,10)});save();flash=`صدرت الوثيقة برقم السجل <b>${rec}</b>`;go();return false}
function resetPw(t,id){const p=pw(),o=(t=='s'?S.students:S.faculty).find(x=>x.id==id);o.pass=p;save();flash=`كلمة المرور الجديدة للحساب <b>${id}</b>: <b>${p}</b>`;go()}
function saveHome(f){S.home={...S.home,...fv(f)};save();flash='حُفظ محتوى الصفحة الرئيسية.';go();return false}
function rstAdmin(){}
function chAdmin(f){flash='بيانات دخول الإدارة تُدار من Supabase (Authentication ← Users) وليس من هنا.';go();return false}
let eu=null;
function toast(m){let t=document.getElementById('ts');if(!t){t=document.createElement('div');t.id='ts';t.className='toast';t.setAttribute('role','status');document.body.appendChild(t)}t.textContent=m;t.classList.toggle('ok37',/^(حُفظ|أُعيد|حُذف|رُصد|قُيِّم|نتيجتك|اعتُمد|تم )/.test(m));t.style.display='block';clearTimeout(t._h);t._h=setTimeout(()=>t.style.display='none',4500)}
let cf=null;
function cfForm(){const c=S.certs.find(x=>x.rec==cf.rec);if(!c){cf=null;return ''}
return cf.t=='rv'?`<div class="msg er"><form onsubmit="return doRevoke(this)"><label>سبب إلغاء الشهادة ${c.rec} (${esc(c.name)})<input name="r" placeholder="مثال: خطأ في البيانات"></label><button class="btn d">تأكيد الإلغاء</button><button type="button" class="btn s" onclick="cf=null;go()">تراجع</button></form></div>`
:`<div class="msg er"><b>حذف نهائي للشهادة ${c.rec} (${esc(c.name)})؟</b> لا يمكن التراجع، وسيختفي رقم السجل من بوابة التحقق. للإبقاء على أثر الوثيقة استخدم «إلغاء» بدل الحذف.<br><button class="btn d" onclick="doDel()">نعم، احذف نهائياً</button> <button class="btn s" onclick="cf=null;go()">تراجع</button></div>`}
function revoke(r){cf={t:'rv',rec:r};go();window.scrollTo(0,0)}
function delCert(r){cf={t:'del',rec:r};go();window.scrollTo(0,0)}
function doRevoke(f){const c=S.certs.find(x=>x.rec==cf.rec);c.revoked=true;c.reason=fv(f).r;c.rdate=new Date().toISOString().slice(0,10);save();flash=`أُلغيت الشهادة ${c.rec}.`;cf=null;go();return false}
function doDel(){S.certs=S.certs.filter(x=>x.rec!=cf.rec);save();flash=`حُذفت الشهادة ${cf.rec} نهائياً.`;cf=null;go()}
function restore(r){const c=S.certs.find(x=>x.rec==r);delete c.revoked;delete c.reason;delete c.rdate;save();flash=`أُعيد تفعيل الشهادة ${r}.`;go()}
function chUser(t,id){eu={t,id};go();window.scrollTo(0,0)}
function userForm(){const o=(eu.t=='s'?S.students:S.faculty).find(x=>x.id==eu.id);return `<div class="msg"><form onsubmit="return saveUser(this)"><label>اسم المستخدم الجديد للحساب ${eu.id} (${esc(o.name)})<input name="u" value="${esc(o.user||'')}" minlength="3" maxlength="30" required autofocus></label><button class="btn">حفظ اسم المستخدم</button><button type="button" class="btn s" onclick="saveUser(this.form,1)">إعادة للرقم الأصلي</button><button type="button" class="btn s" onclick="eu=null;go()">إلغاء</button></form></div>`}
function saveUser(f,reset){const o=(eu.t=='s'?S.students:S.faculty).find(x=>x.id==eu.id),u=reset?'':fv(f).u;
if(u&&[...S.students,...S.faculty].some(x=>x!==o&&(x.id==u||x.user==u))){toast('اسم المستخدم مستخدم من قبل');return false}
o.user=u;save();flash=u?`اسم المستخدم الجديد لـ ${eu.id}: <b>${esc(u)}</b>`:`أُعيد اسم المستخدم إلى ${eu.id}`;eu=null;go();return false}
function setImg(k,u){if(k=='logo2')LOGO2=u;if(k=='logo')LOGO=u;if(k=='seal')SEAL=u;if(k=='sig')SIG=u}
function rstImg(k){delete S.img[k];save();setImg(k,DEF[k]);flash='استُعيدت الصورة الافتراضية.';go()}
