function exEdit(){const e=exFind(xe),c=exCnt(e),q=xq!=null?e.q[xq]:{ty:'mc',t:'',o:['','','',''],c:0};
return `<p><button class="btn s" onclick="xe=null;xq=null;go()">← رجوع</button></p><h3>بيانات الاختبار</h3><form onsubmit="return exSave(this)"><label>العنوان<input name="title" value="${esc(e.title)}"></label><label>العنوان بالإنجليزية (للشهادة)<input name="titleEn" dir="ltr" value="${esc(e.titleEn||'')}"></label><label>اللغة<select name="lang"><option value="ar" ${e.lang=='ar'?'selected':''}>العربية</option><option value="en" ${e.lang=='en'?'selected':''}>الإنجليزية</option></select></label><label>المقرر / المادة<input name="subj" value="${esc(e.subj||'')}"></label><label>المدة بالدقائق<input name="min" type="number" value="${e.min}"></label><button class="btn">حفظ</button> <button type="button" class="btn s" onclick="exDemo()">تعبئة أسئلة تجريبية</button></form>
<h3>${xq!=null?'تعديل سؤال':'إضافة سؤال'} <small class="mu">(الإجمالي ${e.q.length}/40 — الحد الأدنى 10 · اختيار ${c.mc} · صح وخطأ ${c.tf} · كتابة ${c.wr})</small></h3><form onsubmit="return exQ(this)"><label>النوع<select name="ty" onchange="exTy(this.value)">${Object.keys(TYN).map(k=>`<option value="${k}" ${q.ty==k?'selected':''}>${TYN[k]}</option>`).join('')}</select></label><label>نص السؤال<textarea name="t" required>${esc(q.t)}</textarea></label>
<div id="xmc" style="display:${q.ty=='mc'?'block':'none'}">${[0,1,2,3].map(i=>`<label>الخيار ${i+1}<input name="o${i}" value="${esc((q.o||[])[i]||'')}"></label>`).join('')}<label>الإجابة الصحيحة<select name="cm">${[0,1,2,3].map(i=>`<option value="${i}" ${q.ty=='mc'&&q.c==i?'selected':''}>${i+1}</option>`).join('')}</select></label></div>
<div id="xtf" style="display:${q.ty=='tf'?'block':'none'}"><label>الإجابة الصحيحة<select name="ct"><option value="1" ${q.ty=='tf'&&q.c==1?'selected':''}>صح</option><option value="0" ${q.ty=='tf'&&q.c==0?'selected':''}>خطأ</option></select></label></div><button class="btn">${xq!=null?'حفظ التعديل':'إضافة السؤال'}</button>${xq!=null?' <button type="button" class="btn s" onclick="xq=null;go()">إلغاء</button>':''}</form>
<h3>الأسئلة (${e.q.length})</h3>${tbl(['#','النوع','السؤال',''],e.q.map((x,i)=>`<tr><td>${i+1}</td><td>${TYN[x.ty]}</td><td style="white-space:normal">${esc(x.t)}</td><td><button class="btn" onclick="xq=${i};go()">تعديل</button> <button class="btn d" onclick="exDq(${i})">حذف</button></td></tr>`))}`}
function exTy(v){$('#xmc').style.display=v=='mc'?'block':'none';$('#xtf').style.display=v=='tf'?'block':'none'}
function exSave(f){const e=exFind(xe),v=fv(f);Object.assign(e,v,{min:+v.min||90});save();go();return false}
function exQ(f){if(window.exLocked&&exLocked(exFind(xe))){toast('لا يمكن تعديل الأسئلة أثناء نافذة الاختبار المفتوحة');return false}const v=fv(f),x={ty:v.ty,t:v.t},e=exFind(xe);if(v.ty=='mc'){x.o=[v.o0,v.o1,v.o2,v.o3];if(x.o.some(o=>!o)){toast('أكمل الخيارات الأربعة');return false}x.c=+v.cm}if(v.ty=='tf')x.c=+v.ct;xq!=null?e.q[xq]=x:e.q.push(x);xq=null;save();go();return false}
function exDq(i){if(window.exLocked&&exLocked(exFind(xe))){toast('لا يمكن حذف الأسئلة أثناء نافذة الاختبار المفتوحة');return}if(confirm('حذف السؤال؟')){exFind(xe).q.splice(i,1);xq=null;save();go()}}
function exDemo(){const e=exFind(xe),c=exCnt(e);for(let i=c.mc;i<50;i++)e.q.push({ty:'mc',t:'سؤال تجريبي '+(i+1),o:['أ','ب','ج','د'],c:0});for(let i=c.tf;i<45;i++)e.q.push({ty:'tf',t:'عبارة تجريبية '+(i+1),c:1});for(let i=c.wr;i<5;i++)e.q.push({ty:'wr',t:'اكتب فقرة قصيرة رقم '+(i+1)});save();go()}
function exSubs(){return S.subs.length?S.subs.slice().reverse().map(s=>{const e=exFind(s.eid),u=S.students.find(x=>x.id==s.sid)||{name:(s.rid&&(S.requests.find(r=>r.id==s.rid)||{}).name)||'—'},open=false;
return `<div class="box"><b>${esc(u.name)}</b> — ${esc(e.title)} — ${s.date} — <span class="tag ${s.st=='معتمد'?'ok':''}">${s.st}</span> — آلي: ${s.auto}${s.st=='معتمد'?` — الدرجة: <b>${s.total}/${e.q.length}</b> — ${s.rec}`:''}
${open?e.q.map((q,i)=>q.ty=='wr'?`<p class="mu">${esc(q.t)}</p><p>${esc(s.ans[i]||'— لا إجابة —')}</p><label>الدرجة (0–1)<input type="number" min="0" max="1" step="0.25" id="w${s.id}_${i}" value="${s.wr[i]??''}"></label>`:'').join(''):''}
<p>${open?`<button class="btn" onclick="exGrade(${s.id})">حفظ التقييم</button> `:''}${s.st=='مُقيَّم'&&!s.pl?`<input id="ne${s.id}" dir="ltr" placeholder="الاسم بالإنجليزية (اختياري - شهادة ثنائية اللغة)" style="max-width:320px"> <button class="btn" onclick="exAppr(${s.id})">اعتماد وإصدار الشهادة</button> `:''}<button class="btn d" onclick="exDs(${s.id})">حذف</button></p></div>`}).join(''):'<p class="mu">لا تسليمات بعد</p>'}
function exGrade(id){const s=S.subs.find(x=>x.id==id),e=exFind(s.eid);e.q.forEach((q,i)=>{if(q.ty=='wr')s.wr[i]=Math.min(1,Math.max(0,+$('#w'+id+'_'+i).value||0))});s.total=+(s.auto+Object.values(s.wr).reduce((a,b)=>a+b,0)).toFixed(2);s.st='مُقيَّم';save();go()}
function exAppr(id){const s=S.subs.find(x=>x.id==id),e=exFind(s.eid),u=S.students.find(x=>x.id==s.sid),max=e.q.length,pct=Math.round(numOr0(s.total)/Math.max(1,max)*100),en=(($('#ne'+id)||{}).value||'').trim(),rec=v51Serial(0,'exam');
S.certs.push({type:'exam',lang:en?'bi':'',sid:u.id,pid:u.pid,nat:u.nat,name:u.name,nameEn:en,prog:0,examTitle:e.title,examTitleEn:e.titleEn||'',score:s.total,max,pct,level:exLvl(pct),levelEn:exLvlE(pct),grade:s.total+'/'+max,testDate:s.date,rec,date:exToday()});s.st='معتمد';s.rec=rec;save();flash=`اعتُمدت النتيجة وصدرت الشهادة برقم السجل <b>${rec}</b> وتظهر الآن في بوابة الطالب.`;go()}
function exDs(id){if(confirm('حذف التسليم؟')){S.subs=S.subs.filter(x=>x.id!=id);save();go()}}
/* ---- الطالب ---- */
function exStud(s){const mine=S.subs.filter(x=>x.sid==s.id),done=new Set(S.exams.filter(e=>exDone(e,s.id)).map(e=>e.id)),av=S.exams.filter(e=>e.pub&&exWin(e)=='open'&&(e.ready||exReady(e))&&!done.has(e.id)&&(!s.exlang||s.exlang==e.lang));
return `<h3>الاختبارات المتاحة</h3><div class="box">${av.map(e=>`<p><b>${esc(e.title)}</b> — ${EXL[e.lang]} — ${e.min} دقيقة <button class="btn" onclick="exStart(${e.id})">${S.dr[s.id+'_'+e.id]?'متابعة الاختبار':'ابدأ الاختبار'}</button></p>`).join('')||'<p class="mu">لا توجد اختبارات متاحة حالياً</p>'}${mine.length?'<hr>'+mine.map(x=>`<p>${esc((exFind(x.eid)||{title:'—'}).title)} — ${x.date} — <span class="tag ${x.st=='معتمد'?'ok':''}">${x.st=='معتمد'?'معتمد (الشهادة أدناه)':(x.st=='تم الاعتماد والنشر'?'معتمدة ومنشورة':'مُقيَّم آلياً')}</span></p>`).join(''):''}</div>`}
function exStart(id){const k=me.id+'_'+id;S.dr[k]=S.dr[k]||{t:Date.now(),a:{}};save();taking=id;go()}
function exTake(s){const e=exFind(taking),d=S.dr[s.id+'_'+taking];
return `<h2>${esc(e.title)} <small id="xt" class="tag"></small></h2><div class="box">${e.q.map((q,i)=>`<div style="border-bottom:1px dashed #ccc;padding:8px 0"><b>${i+1}. ${esc(q.t)}</b>${q.ty=='mc'?q.o.map((o,j)=>`<label style="display:block"><input type="radio" style="width:auto" name="q${i}" ${d.a[i]===j?'checked':''} onchange="exAns(${i},${j})"> ${esc(o)}</label>`).join(''):q.ty=='tf'?[['صح',1],['خطأ',0]].map(o=>`<label style="display:block"><input type="radio" style="width:auto" name="q${i}" ${d.a[i]===o[1]?'checked':''} onchange="exAns(${i},${o[1]})"> ${o[0]}</label>`).join(''):`<textarea rows="4" oninput="exAns(${i},this.value)">${esc(d.a[i]||'')}</textarea>`}</div>`).join('')}<button class="btn" onclick="exSub(0)">تسليم الاختبار</button> <button class="btn s" onclick="taking=null;go()">حفظ والخروج</button></div><img src="" onerror="exTick();this.remove()" alt="" hidden>`}
function exAns(i,v){S.dr[me.id+'_'+taking].a[i]=v;save()}
function exTick(){clearInterval(xtm);const e=exFind(taking),d=S.dr[me.id+'_'+taking],f=()=>{const t=$('#xt');if(!t||!taking){clearInterval(xtm);return}const r=d.t+e.min*60000-Date.now();if(r<=0){clearInterval(xtm);exSub(1);return}t.textContent='الوقت المتبقي '+Math.floor(r/60000)+':'+String(Math.floor(r%60000/1000)).padStart(2,'0')};f();xtm=setInterval(f,1000)}
function exSub(auto){if(!auto&&!confirm('تأكيد التسليم؟ لا يمكن التعديل بعده.'))return;const e=exFind(taking),k=me.id+'_'+taking,a=S.dr[k].a;let sc=0;e.q.forEach((q,i)=>{if(q.ty!='wr'&&a[i]===q.c)sc++});
S.subs.push({id:Date.now(),sid:me.id,eid:taking,ans:a,auto:sc,wr:{},total:sc,st:'بانتظار التقييم',date:exToday()});delete S.dr[k];taking=null;clearInterval(xtm);save();toast('سُلِّم الاختبار وقُيِّم آلياً وظهرت نتيجتك فوراً');go()}
function exVer(c){return `<div class="msg${c.revoked?' er':''}"><b style="color:var(${c.revoked?'--er':'--ok'})">${c.revoked?'✖ وثيقة ملغاة':'✔ وثيقة معتمدة'}</b><br>الاسم: ${esc(c.name)}<br>الاختبار: ${esc(c.examTitle)}<br>تاريخ الاختبار: ${c.testDate} · الدرجة: ${c.score}/${c.max} · المستوى: ${esc(c.level)}<br>رقم السجل: ${c.rec} · الإصدار: ${c.date}</div>`}

/* ===== ربط Supabase: الحفظ والدخول والتحقق ===== */
let sbAdmin=false,sbT;
const COLS={programs:'programs',news:'news',lib:'library',students:'students',faculty:'faculty',requests:'requests',certs:'certs',docReqs:'doc_requests'},sbKnown={};
const sbId=o=>String(o.rec||o.id),sbStrip=o=>{const c={...o};delete c.pass;return c};
function sbQueue(){if(!sbAdmin||!sb)return;clearTimeout(sbT);sbT=setTimeout(sbPush,700)}
async function sbPush(){for(const [k,t] of Object.entries(COLS)){const rows=(S[k]||[]).map(o=>({id:sbId(o),data:sbStrip(o),updated_at:new Date().toISOString()}));
 if(rows.length){const {error}=await sb.from(t).upsert(rows);if(error){toast('تعذر الحفظ في Supabase ('+t+'): '+error.message);return}}
 const ids=new Set(rows.map(r=>r.id)),del=[...(sbKnown[t]||[])].filter(i=>!ids.has(i));
 if(del.length)await sb.from(t).delete().in('id',del);sbKnown[t]=ids}}
async function sbPull(){for(const [k,t] of Object.entries(COLS)){const {data,error}=await sb.from(t).select('id,data');if(error){toast('خطأ تحميل '+t+': '+error.message);continue}
 sbKnown[t]=new Set(data.map(r=>r.id));
 if(data.length)S[k]=data.map(r=>{const l=(S[k]||[]).find(o=>sbId(o)==r.id);return l&&l.pass?{...r.data,pass:l.pass}:r.data})}
 save();await sbPush()}
async function sbPubPull(){if(!sb)return;try{for(const k of ['programs','news','lib']){const {data,error}=await sb.from(COLS[k]).select('data');if(!error&&data&&data.length)S[k]=data.map(r=>r.data)}save();go()}catch(e){console.error(e)}}
async function sbAdminLogin(v){if(!sb){out('<div class="msg">تعذر الاتصال بالخادم</div>');return}
 const {data:au,error}=await sb.auth.signInWithPassword({email:v.u,password:v.p});if(error){out('<div class="msg">بيانات الدخول غير صحيحة</div>');return}
 const {data:pf}=await sb.from('profiles').select('role').eq('id',au.user.id).maybeSingle();if(!pf||pf.role!='admin'){await sb.auth.signOut();out('<div class="msg">هذا الحساب ليس حساباً إدارياً</div>');return}
 me={r:'admin'};sbUser=null;sbAdmin=true;await sbPull();tab='req';location.hash='#/admin';go()}
function sbOut(){sbAdmin=false;try{sb&&sb.auth.signOut()}catch(e){}}
const vc=c=>c.type=='exam'?exVer(c):`<div class="msg${c.revoked?' er':''}"><b>${c.revoked?'✖ وثيقة ملغاة'+(c.reason?' — '+esc(c.reason):'')+(c.rdate?' ('+esc(c.rdate)+')':''):'✔ وثيقة معتمدة'}</b><br>نوع الوثيقة: ${esc((CT[c.type||'part']||[''])[0])}${c.title?'<br>عنوان الوثيقة: '+esc(c.title):''}${(FR(c.type)&&c.title&&c.name==c.title)?'':'<br>الاسم: '+esc(c.name)}${c.prog?'<br>البرنامج: '+esc(c.prog):''}${(c.hours||c.grade)?'<br>'+(c.hours?'الساعات: '+esc(c.hours):'')+((c.hours&&c.grade)?' · ':'')+(c.grade?'التقدير: '+esc(c.grade):''):''}<br>تاريخ الإصدار: ${esc(c.date)}<br>رقم السجل: ${esc(c.rec)}</div>`;
const _ver=ver;ver=function(f){const q=fv(f).n.trim();if(!sb||!q)return _ver(f);sb.rpc('verify_cert',{q}).then(({data,error})=>{if(!error&&data&&data.length)out(data.map(vc).join(''));else sb.rpc('verify_person',{q}).then(({data:pp})=>{if(pp&&pp.name)out(`<div class="msg"><b style="color:var(--ok)">✔ بطاقة سارية</b><br>الاسم: ${esc(pp.name)}<br>الرقم: ${esc(pp.id)}</div>`);else _ver(f)})});return false};
(async()=>{if(!sb)return;try{const {data:{session}}=await sb.auth.getSession();if(me&&me.r=='admin'){if(!session){me=null;go();return}const {data:pf}=await sb.from('profiles').select('role').eq('id',session.user.id).maybeSingle();if(!pf||pf.role!='admin'){me=null;go();return}sbAdmin=true;await sbPull();go()}else sbPubPull()}catch(e){console.error(e)}})();

