const sbDemo=['1234','tf1234','admin123'],save0=()=>{try{localStorage.setItem(K,JSON.stringify(S))}catch(e){try{window.__lsFail81&&window.__lsFail81(e)}catch(x){}}};
let sbUser=null,PAPER={},exHash={},sbSetH='';
COLS.subs='submissions';
