const sbApplySet=r=>{if(r.key=='home')S.home={...S.home,...r.data};if(r.key=='img'){S.img=r.data||{};['logo','logo2','seal','sig'].forEach(k=>setImg(k,S.img[k]||DEF[k]))}};
