const PH={};let phS={img:null,z:1,x:0,y:0,rot:0};
async function phLoad(id,force){if(PH[id]&&!force)return PH[id];if(!sb)return '';const {data,error}=await sb.storage.from('photos').download(id+'.jpg');if(error||!data)return '';
 return PH[id]=await new Promise(r=>{const f=new FileReader();f.onload=()=>r(f.result);f.readAsDataURL(data)})}
const seeCard=async(t,id)=>{let ph='';try{const u=(t=='s'?S.students:S.faculty).find(x=>x.id==id);if(u&&u.photo)ph=await phLoad(id)}catch(e){}seeCard0(t,id,ph)};
const phPerson=()=>(cf.k=='s'?S.students:S.faculty).find(x=>x.id==cf.id);
function phEdit(k,id){cf={t:'ph',k,id};phS={img:null,z:1,x:0,y:0,rot:0};go();window.scrollTo(0,0)}
const _cfForm2=cfForm;cfForm=function(){return cf&&cf.t=='ph'?phPanel():_cfForm2()};
function phPanel(){const u=phPerson();if(!u){cf=null;return ''}
 return `<div class="msg" id="phpanel"><b>صورة ${esc(u.name)} (${esc(u.id)})</b> ${u.photo?'<span class="tag ok">لها صورة</span>':'<span class="tag">بلا صورة</span>'}<div style="display:flex;gap:16px;flex-wrap:wrap;align-items:flex-start;margin-top:10px"><canvas id="phc" width="600" height="736" style="width:210px;height:258px;border:1px solid var(--bd);border-radius:8px"></canvas>
<div style="flex:1;min-width:230px"><label class="btn" style="cursor:pointer;display:inline-block">${u.photo?'تغيير الصورة':'رفع صورة'}<input type="file" accept="image/*" style="display:none" onchange="phPick(this)"></label>
<label>تكبير<input name="z" type="range" min="1" max="3" step="0.05" value="1" oninput="phSet('z',this.value)"></label><label>يمين / يسار<input name="x" type="range" min="-100" max="100" value="0" oninput="phSet('x',this.value)"></label><label>أعلى / أسفل<input name="y" type="range" min="-100" max="100" value="0" oninput="phSet('y',this.value)"></label>
<button class="btn s" onclick="phRot(-90)">⟲ تدوير</button> <button class="btn s" onclick="phRot(90)">تدوير ⟳</button><br><button class="btn" onclick="phSave()">حفظ وإصدار البطاقة</button> ${u.photo?'<button class="btn d" onclick="phDel()">حذف الصورة</button> ':''}<button class="btn s" onclick="cf=null;go()">إغلاق</button></div></div></div><img src="" onerror="phInit();this.remove()" alt="" hidden>`}
async function phInit(){const u=phPerson();if(u&&u.photo){const d=await phLoad(cf.id,true);if(d){const im=new Image();im.onload=()=>{phS.img=im;phDraw()};im.src=d}}phDraw()}
function phDraw(){const c=$('#phc');if(!c)return;const g=c.getContext('2d');g.fillStyle='#e8ecf4';g.fillRect(0,0,c.width,c.height);const im=phS.img;
 if(!im){g.fillStyle='#8a94a8';g.font='34px sans-serif';g.textAlign='center';g.fillText('لا توجد صورة',c.width/2,c.height/2);return}
 const sw=phS.rot%180?im.height:im.width,sh=phS.rot%180?im.width:im.height,s=Math.max(c.width/sw,c.height/sh)*phS.z;
 g.save();g.translate(c.width/2+phS.x*c.width/200,c.height/2+phS.y*c.height/200);g.rotate(phS.rot*Math.PI/180);g.scale(s,s);g.drawImage(im,-im.width/2,-im.height/2);g.restore()}
function phSet(k,v){phS[k]=+v;phDraw()}
function phRot(d){phS.rot=((phS.rot+d)%360+360)%360;phDraw()}
function phPick(inp){const f=inp.files&&inp.files[0];if(!f)return;if(!/^image\//.test(f.type)){toast('اختر ملف صورة (JPG أو PNG)');return}if(f.size>15e6){toast('الصورة كبيرة جداً (الحد 15 ميغابايت)');return}
 const r=new FileReader();r.onload=()=>{const im=new Image();im.onload=()=>{phS={img:im,z:1,x:0,y:0,rot:0};document.querySelectorAll('#phpanel input[type=range]').forEach(i=>i.value=i.name=='z'?1:0);phDraw()};im.onerror=()=>toast('تعذّر قراءة الصورة');im.src=r.result};r.readAsDataURL(f)}
async function phSave(){const u=phPerson();if(!phS.img){toast('اختر صورة أولاً');return}if(!sb||!sbAdmin){toast('يلزم الدخول كمدير');return}
 const c=$('#phc'),blob=await new Promise(r=>c.toBlob(r,'image/jpeg',.85)),id=cf.id,k=cf.k;
 const {error}=await sb.storage.from('photos').upload(id+'.jpg',blob,{upsert:true,contentType:'image/jpeg'});if(error){toast('تعذّر رفع الصورة: '+error.message);return}
 u.photo=Date.now();PH[id]=c.toDataURL('image/jpeg',.85);save();cf=null;flash='حُفظت الصورة وأُصدرت البطاقة تلقائياً بالصورة الجديدة.';go();seeCard(k,id)}
async function phDel(){if(!confirm('حذف الصورة نهائياً؟'))return;const u=phPerson(),id=cf.id;try{await sb.storage.from('photos').remove([id+'.jpg'])}catch(e){}
 delete u.photo;delete PH[id];save();cf=null;flash='حُذفت الصورة، وستظهر في البطاقة الأحرف الأولى من الاسم.';go()}

