{const st=document.createElement('style');st.textContent='.xov{position:fixed;top:0;right:0;bottom:0;left:0;background:rgba(10,20,40,.55);z-index:60;overflow:auto;padding:24px 12px}.xpn{max-width:720px;margin:0 auto;background:var(--sf,#fff);color:var(--tx,#14213d);border-radius:16px;padding:18px;box-shadow:0 10px 40px rgba(0,0,0,.35)}.xt{width:100%;border-collapse:collapse;margin-top:10px}.xt td{border-bottom:1px solid var(--bd,#d9deea);padding:8px 6px;vertical-align:top}.xt td:first-child{color:var(--mu,#5b6578);width:38%;font-weight:600}';document.head.appendChild(st)}
