const xo=(t,b)=>`<div class="xov" onclick="if(event.target==this){cf=null;go()}"><div class="xpn"><div style="display:flex;justify-content:space-between;align-items:center;gap:10px"><h3 style="margin:0">${t}</h3><button class="btn s" onclick="cf=null;go()">✕ إغلاق</button></div><hr>${b}</div></div>`;
