function reviewReq(id){cf={t:'rvw',id,edit:false};go();window.scrollTo(0,0)}
function rvwBody(){const r=xel(cf.id);if(!r){cf=null;return ''}
 const pn=(S.programs.find(p=>p.id==r.prog)||{}).name||r.progName||'—',pend=r.status=='قيد المراجعة';
 if(cf.edit)return `<form onsubmit="return saveRq(this)">${xi('name','الاسم الكامل',r.name,'required')}${xi('email','البريد',r.email,'type="email"')}${xi('phone','رقم الجوال',r.phone)}${xs('sex','الجنس',['ذكر','أنثى'],r.sex)}${xi('nat','الجنسية',r.nat)}${xi('pid','رقم الهوية / الجواز',r.pid,'required')}${xs('prog','البرنامج',S.programs.map(p=>[p.id,p.name]),r.prog)}${xs('exlang','اختبار تحديد المستوى',[['ar','اختبار تحديد المستوى في اللغة العربية']],'ar')}<button class="btn">حفظ التعديلات</button> <button type="button" class="btn s" onclick="cf.edit=false;go()">تراجع</button></form>`;
 const V={...r,prog:pn,exlang:XEX[r.exlang||'']||r.exlang,pl:plOf(r)?(plOf(r).score+' / 100 — المستوى المقترح: '+PLN[plOf(r).lv||plLvN(plOf(r).score)]+(plOf(r).date?' — '+plOf(r).date:'')):undefined},keys=Object.keys(XL),ex=Object.keys(r).filter(k=>!keys.includes(k)&&k!='progName'&&k!='pl'&&!/^(placement|suggestedLevel)/.test(k));
 return `<span class="tag ${r.status=='مقبول'?'ok':r.status=='مرفوض'?'er':''}">${esc(r.status)}</span>${plReviewBox(r)}<table class="xt">${keys.filter(k=>V[k]!==undefined&&V[k]!=='').map(k=>`<tr><td>${XL[k]}</td><td>${esc(V[k])}</td></tr>`).join('')}${ex.map(k=>`<tr><td>${esc(k)}</td><td>${esc(typeof r[k]=='object'?JSON.stringify(r[k]):r[k])}</td></tr>`).join('')}</table><p style="margin-top:14px">${pend?`<button class="btn" onclick="cf=null;decide('${r.id}',1)">✔ قبول</button> <button class="btn d" onclick="cf=null;decide('${r.id}',0)">✖ رفض</button> `:''}<button class="btn s" onclick="cf.edit=true;go()">✎ تعديل البيانات</button></p>`}
function saveRq(f){const r=xel(cf.id),v=fv(f);Object.assign(r,v,{prog:+v.prog});r.progName=(S.programs.find(p=>p.id==r.prog)||{}).name||'';
 const s=S.students.find(x=>x.id==r.sid);if(s)Object.assign(s,{name:r.name,email:r.email,phone:r.phone,sex:r.sex,nat:r.nat,pid:r.pid,prog:r.prog,exlang:r.exlang});
 cf.edit=false;save();flash='حُفظت تعديلات الطلب'+(s?' وحُدِّثت بيانات الطالب المرتبط به.':'.');go();return false}
