function addStu(f){const v=fv(f);if(v.pid&&S.students.some(x=>x.pid==v.pid)){toast('رقم الهوية مسجَّل لطالب آخر');return false}
 const id='ST-2026-'+pad(S.n.st++),p=pw();S.students.push({...v,id,prog:+v.prog,pass:p,adm:window.adm48parse?adm48parse(v.adm):undefined});if(window.adm48log)adm48log('تسجيل طالب يدوياً',id,v.name);cf=null;save();
 flash=`أُضيف الطالب. الرقم الأكاديمي: <b>${id}</b> · الدخول برقم الجواز: <b>${esc(v.pid)}</b> · كلمة المرور: <b>${p}</b>${xw(v.name,v.email,v.pid,p,'رقم الجواز')}`;go();return false}
