const tpl=(t,ps,c)=>`<div dir="rtl" style="font-family:Tahoma,Arial,sans-serif;max-width:560px;margin:auto;border:1px solid #d9deea;border-radius:10px;overflow:hidden"><div style="background:#13306b;color:#fff;padding:14px 18px;font-size:18px">معهد التمهيد</div><div style="padding:18px;line-height:1.9;color:#14213d"><h3 style="margin:0 0 8px">${esc(t)}</h3>${ps.map(p=>`<p style="margin:6px 0">${esc(p)}</p>`).join('')}${c?`<p><a href="${esc(c[1])}" style="background:#13306b;color:#fff;padding:8px 16px;border-radius:6px;text-decoration:none;display:inline-block">${esc(c[0])}</a></p>`:''}</div></div>`;
