const nE=s=>String(s||'').trim().toLowerCase(),nP=s=>String(s||'').trim().toUpperCase().replace(/\s+/g,'');
/* v97: التكرار يُمنع داخل الفئة الواحدة فقط — الخريج قد يُعيَّن عضواً في هيئة التدريس أو الإدارة بهويته وبريده نفسيهما (الشخص نفسه) */
function conflicts(v,self,kind){const out=[];[...(kind!=='f'?S.students.map(x=>['طالب',x]):[]),...(kind!=='s'?S.faculty.map(x=>['عضو هيئة',x]):[])].forEach(([k,x])=>{if(self&&x.id==self)return;
if(v.email&&nE(x.email)==nE(v.email))out.push({f:'email',msg:'البريد «'+v.email+'» مسجَّل مسبقاً لـ'+k+': '+x.name+' ('+x.id+')'});
if(v.pid&&nP(x.pid)==nP(v.pid))out.push({f:'pid',msg:'رقم الهوية/الجواز «'+v.pid+'» مسجَّل مسبقاً لـ'+k+': '+x.name+' ('+x.id+')'})});return out}
const FK={addStu:['s',0],saveStu:['s',1],addTF2:['f',0],saveTF:['f',1]};
function chk(f,fn){const[k,ed]=FK[fn],v=fv(f),e=[];
if((v.name||'').length<3)e.push({f:'name',msg:'الاسم قصير جداً (3 أحرف على الأقل)'});
if(v.email&&!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v.email))e.push({f:'email',msg:'صيغة البريد غير صحيحة'});
if(v.phone&&!/^[+\d][\d\s\-()]{6,19}$/.test(v.phone))e.push({f:'phone',msg:'رقم الجوال غير صالح (أرقام فقط مع + اختيارية)'});
if(v.pid&&!/^[A-Za-z0-9\-\/]{4,25}$/.test(v.pid))e.push({f:'pid',msg:'رقم الهوية/الجواز غير صالح (4–25 حرفاً أو رقماً)'});
if(k=='s'&&!v.pid)e.push({f:'pid',msg:'رقم الهوية/الجواز مطلوب'});
return e.concat(conflicts(v,ed?cf&&cf.id:null,k))}
function showErr(f,errs){let b=f.querySelector('.vbox');f.querySelectorAll('[aria-invalid]').forEach(x=>x.removeAttribute('aria-invalid'));
if(!errs.length){b&&b.remove();return}
if(!b){b=document.createElement('div');b.className='msg er vbox';b.setAttribute('role','alert');b.style.gridColumn='1/-1';f.prepend(b)}
b.innerHTML='<b>⚠ تنبيه قبل الحفظ:</b><br>'+errs.map(x=>esc(x.msg)).join('<br>');errs.forEach(x=>{const el=f.elements[x.f];if(el)el.setAttribute('aria-invalid','true')})}
const vpre=fn=>f=>{const errs=chk(f,fn);showErr(f,errs);if(errs.length){toast(errs[0].msg);const el=f.elements[errs[0].f];el&&el.focus();return false}
if(fn=='addStu')while(S.students.some(x=>x.id=='ST-2026-'+pad(S.n.st)))S.n.st++;
if(fn=='addTF2')while(S.faculty.some(x=>x.id=='TF-2026-'+pad(S.n.tf)))S.n.tf++};
