function hook(name,o){const f=window[name];if(typeof f!='function')return;window[name]=function(...a){if(o.pre&&o.pre.apply(this,a)===false)return false;const b=snap(),rv=f.apply(this,a);
try{const d=diff(b,snap());if(d.n){const s=summ(d);audit(typeof o.label=='function'?o.label(...a):o.label,s.target,s.detail);if(o.post)o.post(d,a)}}catch(e){console.error(e)}return rv}}
