const nowX=()=>new Date(Date.now()+EX_TZ*36e5).toISOString().slice(0,19);
window.exLocked=e=>!!e&&exWin(e)=='open';
function exWin(e){if(!e||!e.date||!e.end)return 'none';const n=nowX();if(n<e.date)return 'before';if(n>=e.end)return 'after';return 'open'}
const exFmt=s=>String(s||'').replace('T',' ');
