{const _x9=exStart;exStart=function(id){const e=S.exams.find(x=>x.id==id);if(exWin(e)!='open'){toast('الاختبار خارج وقته المحدد ولا يمكن الدخول إليه');go();return}return _x9.apply(this,arguments)}}
