/* ---- جدولة متعددة الأيام والأوقات ---- */
const tm=v=>{if(!v)return '';const[h,m]=String(v).split(':').map(Number);if(isNaN(h))return esc(v);return ((h%12)||12)+':'+String(m||0).padStart(2,'0')+' '+(h>=12?'م':'ص')};
function slotsOf(c){if(c&&Array.isArray(c.slots)&&c.slots.length)return c.slots;return c&&c.day!=null&&!isNaN(c.day)&&(c.from||c.to)?[{day:+c.day,from:c.from,to:c.to,room:c.room}]:[]}
const slotsTxt=c=>{const L=slotsOf(c).slice().sort((a,b)=>a.day-b.day||String(a.from).localeCompare(b.from));return L.length?L.map(s=>`${DAYS[s.day]||'—'} ${esc(tm(s.from))}${s.to?' – '+esc(tm(s.to)):''}`).join('<br>'):'—'};
function FLAT(L){const o=[];L.forEach(c=>{const s=slotsOf(c);if(!s.length)o.push({...c,day:undefined,from:'',to:''});else s.forEach(x=>o.push({...c,day:x.day,from:x.from,to:x.to,room:x.room||c.room}))});return o}
const slotRow=(s,i)=>`<div class="slr"><label>اليوم<select ${i==0?'name="day"':''} class="sd">${DAYS.map((d,k)=>k>=1&&k<=5?`<option value="${k}" ${k==((s.day>=1&&s.day<=5)?s.day:1)?'selected':''}>${d}</option>`:'').join('')}</select></label><label>من<input type="time" ${i==0?'name="from"':''} class="sf" value="${esc(s.from||'')}"></label><label>إلى<input type="time" ${i==0?'name="to"':''} class="st" value="${esc(s.to||'')}"></label><label>القاعة / رابط الحصة<input ${i==0?'name="room"':''} class="sr" value="${esc(s.room||'')}"></label>${i?'<button type="button" class="btn d" onclick="this.closest(\'.slr\').remove()" aria-label="حذف هذا الموعد">حذف</button>':'<span></span>'}</div>`;
function slotsEd(e){const L=slotsOf(e);const rows=(L.length?L:[{day:0}]).map(slotRow).join('');return `<div class="slx"><b>أيام المحاضرات وأوقاتها (يمكن إضافة عدة أيام للمقرر نفسه)</b><div id="slbox" style="display:grid;gap:8px;margin-top:6px">${rows}</div><button type="button" class="btn s" onclick="addSlot()">+ إضافة يوم ووقت آخر</button></div>`}
function addSlot(){const b=document.getElementById('slbox');if(!b)return;b.insertAdjacentHTML('beforeend',slotRow({day:2},b.children.length))}
function readSlots(f){const o=[];f.querySelectorAll('.slr').forEach(r=>o.push({day:+r.querySelector('.sd').value,from:r.querySelector('.sf').value,to:r.querySelector('.st').value,room:r.querySelector('.sr').value.trim()}));return o}
{const _s9=saveCr;saveCr=function(f){const sl=readSlots(f);for(const s of sl){if((s.from&&!s.to)||(!s.from&&s.to)){toast('حدّد وقت البداية والنهاية لكل يوم');return false}if(s.from&&s.to&&s.to<=s.from){toast('وقت نهاية المحاضرة يجب أن يكون بعد بدايتها');return false}}
const ok=sl.filter(s=>s.from&&s.to);for(let i=0;i<ok.length;i++)for(let j=i+1;j<ok.length;j++)if(ok[i].day==ok[j].day&&ok[i].from<ok[j].to&&ok[j].from<ok[i].to){toast('يوجد تداخل بين موعدين في '+DAYS[ok[i].day]);return false}
const eid=crE,n=crs().length,r=_s9.apply(this,arguments),L=crs(),c=eid?L.find(x=>x.id==eid):(L.length>n?L[L.length-1]:null);if(c){c.slots=ok;if(ok[0]){c.day=ok[0].day;c.from=ok[0].from;c.to=ok[0].to;c.room=ok[0].room}save()}return r}}
/* الجدول الأسبوعي التفصيلي للطالب */
function weekly(s,L,ins){const R=FLAT(L).filter(x=>x.day!=null&&x.from);if(!R.length)return '';R.sort((a,b)=>a.day-b.day||String(a.from).localeCompare(b.from));
const dur=x=>{if(!x.to)return '';const m=(+x.to.slice(0,2)*60+ +x.to.slice(3))-(+x.from.slice(0,2)*60+ +x.from.slice(3));return m>0?(m/60).toFixed(m%60?1:0).replace(/\.0$/,'')+' ساعة':''};
const cnt={};R.forEach(x=>cnt[x.day]=(cnt[x.day]||0)+1);const seen={};let tot=0;R.forEach(x=>{const m=(+x.to.slice(0,2)*60+ +x.to.slice(3))-(+x.from.slice(0,2)*60+ +x.from.slice(3));if(m>0)tot+=m});
return `<h3>جدولي الأسبوعي</h3><div class="box"><div class="tw"><table class="wk"><tr><th>اليوم</th><th>الوقت</th><th>المقرر</th><th>المدة</th><th>الأستاذ</th><th>القاعة / الرابط</th></tr>${R.map(x=>{const first=!seen[x.day];seen[x.day]=1;return `<tr>${first?`<td rowspan="${cnt[x.day]}">${DAYS[x.day]}</td>`:''}<td>${esc(tm(x.from))} – ${esc(tm(x.to))}</td><td>${esc(x.name)}${x.code?' <small>('+esc(x.code)+')</small>':''}</td><td>${dur(x)}</td><td>${esc(ins(x))}</td><td>${esc(x.room||'—')}</td></tr>`}).join('')}</table></div><p class="mu">إجمالي ساعات المحاضرات أسبوعياً: <b>${(tot/60).toFixed(tot%60?1:0).replace(/\.0$/,'')}</b> ساعة، موزعة على ${Object.keys(cnt).length} أيام.</p></div>`}


