const CALMIN=16,calWk=(a,b)=>a&&b?Math.ceil((new Date(b)-new Date(a)+864e5)/6048e5):null;
const calGet=l=>{const c=(P(DIP).cal||{})[l]||{};return{year:c.year||('السنة الدراسية '+(l<3?'الأولى':'الثانية')),name:c.name||DEFR.sem[l],from:c.from||'',to:c.to||'',weeks:c.weeks||''}};
const calBox=()=>{const R=window.rcfg();return `<h3>التقويم الأكاديمي (فصلان دراسيان في السنة · لا يقل الفصل عن ${CALMIN} أسبوعاً)</h3><div class="box">${tbl(['السنة','الفصل','المستوى','البداية','النهاية','الأسابيع'],[1,2,3,4].map(l=>{const c=calGet(l);return `<tr><td>${esc(c.year)}</td><td>${esc(c.name)}</td><td>${esc(R.lvl[l])}</td><td>${esc(c.from||'—')}</td><td>${esc(c.to||'—')}</td><td>${c.weeks||'—'}</td></tr>`}))}</div>`+(typeof acalPublic=='function'?acalPublic():'')};
function calAdmin(){const R=window.rcfg(),I=(n,v,x)=>`<input name="${n}" value="${esc(v)}" ${x||''}>`;
return `<p class="mu">تتكوّن السنة الأكاديمية من فصلين دراسيين حصراً: المستويان الأول والثاني = السنة الأولى، والثالث والرابع = السنة الثانية. تظهر البيانات فوراً في السجل الأكاديمي وجداول الطلاب والأساتذة، وتُجلب مسميات الفصول والأعوام آلياً من التقويم الأكاديمي المعتمد.</p><form onsubmit="return calSave(this)" style="display:block">${tbl(['المستوى','السنة','اسم الفصل','اسم المستوى','البداية','النهاية','الأسابيع (≥16)'],[1,2,3,4].map(l=>{const c=calGet(l);return `<tr><td>${l}</td><td>${I('y'+l,c.year)}</td><td>${I('n'+l,c.name,'required')}</td><td>${I('l'+l,R.lvl[l])}</td><td>${I('f'+l,c.from,'type="date"')}</td><td>${I('t'+l,c.to,'type="date"')}</td><td>${I('w'+l,c.weeks,'type="number" min="16" max="60"')}</td></tr>`}))}<button class="btn">حفظ التقويم</button></form>`+calBox()}
function calSave(f){const v=fv(f),D=P(DIP),cal={},bad=m=>{toast(m);return false};let prev='';
for(const l of [1,2,3,4]){const a=v['f'+l],b=v['t'+l],sp=calWk(a,b);let w=+v['w'+l]||sp||0;
if(a&&b&&b<=a)return bad('المستوى '+l+': تاريخ النهاية يجب أن يلي البداية');
if(a&&prev&&a<=prev)return bad('المستوى '+l+': يجب أن يبدأ بعد نهاية الفصل السابق');
if(!w)return bad('المستوى '+l+': أدخل عدد الأسابيع أو تاريخَي البداية والنهاية');
if(w<CALMIN)return bad('المستوى '+l+': لا يقل الفصل الدراسي عن '+CALMIN+' أسبوعاً');
if(sp&&sp<w)return bad('المستوى '+l+': المدة بين التاريخين ('+sp+' أسبوعاً) أقل من عدد الأسابيع المدخل');
if(b)prev=b;cal[l]={year:v['y'+l],name:v['n'+l],from:a,to:b,weeks:w}}
D.cal=cal;const rc=D.rcfg=D.rcfg||{};rc.sem=rc.sem||{};rc.lvl=rc.lvl||{};[1,2,3,4].forEach(l=>{rc.sem[l]=cal[l].name;rc.lvl[l]=v['l'+l]||DEFR.lvl[l]});rc.weeks=Math.min(...[1,2,3,4].map(l=>cal[l].weeks));
save();if(window.audit4)audit4('تحديث التقويم الأكاديمي','—','4 مستويات');flash='حُفظ التقويم الأكاديمي وظهر في السجلات والجداول.';go();return false}
let calCtx=0;const _rc7=window.rcfg;window.rcfg=function(){const R=_rc7.apply(this,arguments);if(!calCtx)return R;const sem={},ws=[];[1,2,3,4].forEach(l=>{const c=calGet(l),w=+c.weeks||0;if(w)ws.push(w);sem[l]=c.year+' — '+c.name+(c.from&&c.to?' ('+c.from+' ← '+c.to+(w?' · '+w+' أسبوعاً':'')+')':'')});return{...R,sem,weeks:ws.length?Math.max(CALMIN,Math.min(...ws)):R.weeks}};
