const PLID=1000001;
const PLTF=[['الفاعل في اللغة العربية يكون مرفوعاً دائماً.',1],['جمع المذكر السالم يُرفع بالواو وينصب ويجر بالياء.',1],['الفعل المضارع يكون مبنياً إذا اتصلت به نون التوكيد اتصالاً مباشراً.',1],['كلمة "أخوك" من الأسماء الخمسة وتُرفع بالواو.',1],['المفعول به دائماً مجرور بحرف جر أصلي.',0],['همزة الوصل تثبت في بدء الكلام وتَسقط في درجه (وصله).',1],['المصدر الصريح يدل على حدث غير مقترن بزمن.',1],['اسم الفاعل من الفعل الثلاثي يُصاغ دائماً على وزن "مَفْعُول".',0],['حروف الجر تجر الاسم الواقع بعدها بالكسرة الظاهرة فقط دون علامات أخرى.',0],['المبتدأ والخبر مرفوعان دائماً إذا لم يدخل عليهما ناسخ (كان أو إنّ وأخواتهما).',1],['الفعل الماضي مبني دائماً على الفتح الظاهر فقط.',0],['جمع التكسير يعامل معاملة المفرد المؤنث تماماً في إعرابه.',0],['النعت يتبع المنعوت في إعرابه وتذكيره وتأنيثه وتعريفه وتنكيره.',1],['الفعل "بئس" هو فعل ماضٍ جامد يفيد المدح.',0],['الحال يكون نكرة منصوبة دائماً ويبين هيئة صاحبه المعرفة غالباً.',1],['التمييز اسم نكرة جامد يذكر لإزالة الإبهام عما قبله.',1],['المنادى العلم المفرد يكون مبنياً على ما يُرفع به في محل نصب.',1],['البدل يتبع المبدل منه في إعرابه رفعاً ونصباً وجراً.',1],['الممنوع من الصرف يجر بالفتحة نيابة عن الكسرة إذا كان مجرداً من "أل" والإضافة.',1],['تمييز "كم" الاستفهامية يكون جمعاً مجروراً.',0],['الفعل المضارع المعتل الآخر بالواو يُنصب بفتحة ظاهرة على آخره.',1],['"لا" النافية للجنس تبني اسمها المفرد على الفتح في محل نصب.',1],['أسلوب الاستثناء بـ "خلا" يجوز فيه النصب على الاستثناء أو الجر على أنه حرف جر.',1],['همزة القطع تُنطق في ابتداء الكلام ودرجه.',1],['المضاف إليه يكون مجروراً دائماً.',1]];
const PLMC=[['ما الوزن الصرفي الصحيح لكلمة "انتصار"؟','افتعال',['انفعال','استفعال','تفاعل']],['أي الكلمات الآتية تُعد "ممنوعة من الصرف" لعلة واحدة (صيغة منتهى الجموع)؟','مساجد',['مسجد','كتاب','معلمون']],['ما إعراب كلمة "الطالبَ" في جملة: "إنَّ الطالبَ مجتهدٌ"؟','اسم إنَّ منصوب وعلامة نصبه الفتحة الظاهرة',['اسم إنَّ مرفوع وعلامة رفعه الضمة الظاهرة','مبتدأ منصوب وعلامة نصبه الفتحة','فاعل منصوب وعلامة نصبه الفتحة']],['ما نوع الكلمة "استغفَرَ" من حيث التجرد والزيادة؟','فعل ثلاثي مزيد بثلاثة أحرف',['فعل ثلاثي مجرد','فعل ثلاثي مزيد بحرف واحد','فعل رباعي مجرد']],['في جملة: "حضر الطالبانِ كلاهما"، ما إعراب كلمة "كلاهما"؟','توكيد معنوي مرفوع وعلامة رفعه الألف لأنه ملحق بالمثنى',['توكيد لفظي مرفوع وعلامة رفعه الضمة','نعت مرفوع وعلامة رفعه الألف','بدل مرفوع وعلامة رفعه الضمة']],['ما نوع الفعل في قوله تعالى: "قالَ ربّ أنَّى يكون لي غُلام"؟','مضارع',['ماضٍ','أمر','جامد']],['ما علامة جر الممنوع من الصرف إذا كان مقترناً بـ (أل) أو الإضافة؟','الكسرة الظاهرة',['الفتحة نيابة عن الكسرة','الياء','السكون']],['ما إعراب كلمة "زيدٌ" في جملة: "ما جاءَ إلا زيدٌ"؟','فاعل مرفوع وعلامة رفعه الضمة',['مستثنى منصوب وعلامة نصبه الفتحة','مبتدأ مرفوع وعلامة رفعه الضمة','مفعول به منصوب وعلامة نصبه الفتحة']],['أي الكلمات التالية تُعَد من الأفعال الخمسة؟','يكتبون و يكتبانِ معاً',['كتبوا وكتبتْ','يكتبُ وتكتبُ','كاتبون وكاتبان']],['ما نوع الخبر في جملة: "العلمُ فوائدُه عظيمةٌ"؟','خبر جملة اسمية',['خبر مفرد','خبر جملة فعلية','خبر شبه جملة']],['علامة نصب "جمع المؤنث السالم" هي:','الكسرة نيابة عن الفتحة',['الفتحة الظاهرة','الياء نيابة عن الكسرة','الألف نيابة عن الفتحة']],['ما هي علامة رفع الفعل المضارع الصحيح الآخر؟','الضمة الظاهرة',['الفتحة الظاهرة','السكون','ثبوت النون']],['ما نوع المفعول المطلق في جملة: "سيرتُ سَيْراً طويلاً"؟','مبين للنوع',['مؤكد للفعل','مبين للعدد','نائب عن المفعول المطلق']],['الكلمة المبنية من الكلمات الآتية هي:','هذا',['رجل','كتاب','معلمٌ']],['ما نوع النعت في جملة: "جاء رجلٌ يمشِي"؟','نعت جملة فعلية',['نعت مفرد','نعت جملة اسمية','نعت شبه جملة']]];
const plBank=()=>PLTF.map(x=>({ty:'tf',t:x[0],c:x[1]})).concat(PLMC.map((x,i)=>{const p=i%4,o=x[2].slice();o.splice(p,0,x[1]);return{ty:'mc',t:x[0],o,c:p}}));
function plMainEnsure(){let e=S.exams.find(x=>x.id==PLID),ch=false;if(!e){e={id:PLID};S.exams.push(e);ch=true}
const q=plBank();if(JSON.stringify(e.q)!=JSON.stringify(q)||!e.pub||e.lang!='ar'||e.date||e.title!='اختبار تحديد المستوى في اللغة العربية'){Object.assign(e,{title:'اختبار تحديد المستوى في اللغة العربية',titleEn:'Arabic Placement Test',lang:'ar',subj:'تحديد المستوى',min:60,pub:true,perm:1,date:'',q,ready:true});ch=true}if(ch)save()}
const _goBase=go;go=function(){plMainEnsure();GOH.pre.forEach(h=>h());ensureDip();const r=_goBase.apply(this,arguments);[verAuto,...GOH.post].forEach(h=>{try{h()}catch(e){console.error(e)}});return r};
const _xd8=exDel;exDel=function(id){if(id==PLID){toast('اختبار تحديد المستوى الرئيسي ثابت ولا يُحذف');return}return _xd8.apply(this,arguments)};
const _xp8=exPub;exPub=function(id){if(id==PLID){toast('اختبار تحديد المستوى الرئيسي مفتوح على الدوام');return}return _xp8.apply(this,arguments)};
const _xs8=exStart;exStart=function(id){if(id==PLID){toast('هذا الاختبار مخصص للمتقدمين برقم الطلب');return}return _xs8.apply(this,arguments)};
plMainEnsure();

addEventListener('hashchange',()=>window.go());go();
